/** An HTTP failure carrying the server status so callers can branch on 401/403 without parsing text. */
export class GatewayHttpError extends Error {
  constructor(public readonly status: number) {
    super(`gateway ${status}`);
    this.name = 'GatewayHttpError';
  }
}

/**
 * Thrown by the `fetch*` read variants (no fixture fallback) when the gateway is disabled or
 * unreachable. Callers use it to fall back themselves while keeping provenance (`ReadSource`).
 */
export class GatewayOfflineError extends Error {
  constructor() {
    super('gateway offline');
    this.name = 'GatewayOfflineError';
  }
}

/**
 * How the client is currently authenticating. Diagnostic only — never used to gate a write.
 *  - `dev-bypass` — dev-only `X-Dev-User` override against an `AUTH_DISABLED=true` gateway.
 *  - `enterprise` — a Keychain-stored Firebase ID token (verified server-side).
 *  - `none`       — no token/override configured.
 */
export type GatewayAuthStatus = 'dev-bypass' | 'enterprise' | 'none';

/**
 * One `admins.app_config` row served to the app from `GET /app-config`. Only public rows are ever
 * returned to the client (superadmin-only / secret rows are masked and unlisted). `value` is the
 * raw JSONB value — a string, number, boolean, or nested object/array depending on the key.
 */
export interface AppConfigRow {
  key: string;
  category: 'brand' | 'maps' | 'region' | 'feature' | 'maintenance' | 'limits';
  value: any;
  isPublic: boolean;
  appVariant: 'customer' | 'delivery' | 'seller' | 'all';
  valueSecret?: boolean;
  description?: string;
  updatedAt?: string;
}

/** Build a `?a=b&c=d` string from defined, non-empty filter values. */
function queryString(params?: Record<string, string | undefined>): string {
  if (!params) return '';
  const parts = Object.entries(params)
    .filter(([, v]) => v !== undefined && v !== '')
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v as string)}`);
  return parts.length ? `?${parts.join('&')}` : '';
}

