  /**
   * Server-authoritative delivery-fee quote for a store → drop distance
   * (GET /checkout/delivery-fee; the server owns the road-distance math from
   * directory.stores + the tax.delivery_fee_settings rate card). Throws
   * `GatewayOfflineError` when remote is disabled, so the caller's honest
   * Haversine + client-formula estimate (utils.computeDeliveryFeePaisa) is the
   * fallback seam — a quote is never fabricated from a fixture.
   */
  async fetchDeliveryFee(
    storeId: string,
    lat: number,
    lng: number,
  ): Promise<DeliveryFeeBreakdown> {
    if (!REMOTE_ENABLED) throw new GatewayOfflineError();
    const raw = await this.http<Partial<DeliveryFeeBreakdown>>(
      `/checkout/delivery-fee?storeId=${encodeURIComponent(storeId)}&lat=${lat}&lng=${lng}`,
    );
    // Tolerate a pre-surge gateway (only `distanceKm` + `feePaisa`) during a rolling deploy:
    // treat the legacy total as the base row instead of rendering NaN.
    const totalPaisa = raw.totalPaisa ?? raw.feePaisa ?? 0;
    return {
      distanceKm: raw.distanceKm ?? 0,
      zoneId: raw.zoneId,
      baseDistanceKm: raw.baseDistanceKm ?? 3,
      baseFeePaisa: raw.baseFeePaisa ?? totalPaisa,
      extraKmPaisa: raw.extraKmPaisa ?? 0,
      nightSurgePaisa: raw.nightSurgePaisa ?? 0,
      weatherSurgePaisa: raw.weatherSurgePaisa ?? 0,
      festivalSurgePaisa: raw.festivalSurgePaisa ?? 0,
      totalPaisa,
      feePaisa: raw.feePaisa ?? totalPaisa,
      surgeReasons: raw.surgeReasons ?? [],
    };
  }

  /** Durable self-pickup locations (public). Falls back to the store-backed resolver. */
  async getPickupPoints(storeIds?: string[]): Promise<PickupPoint[]> {
    return this.withFallback(
      () =>
        this.http<PickupPoint[]>(
          `/pickup-points${storeIds && storeIds.length ? `?storeIds=${encodeURIComponent(storeIds.join(','))}` : ''}`,
        ),
      () => {
        const wanted = new Set(storeIds ?? []);
        const points: PickupPoint[] = storeDirectory
          .filter((s) => (wanted.size === 0 || wanted.has(s.id)) && s.address && s.phone && s.hours)
          .map((s) => ({ id: s.id, name: s.name, address: s.address as string, phone: s.phone as string, hours: s.hours as string, isActive: true }));
        if (points.length === 0) points.push(NEUTRAL_PICKUP);
        return delay(points);
      },
    );
  }

